    /// never through a link; one made is private (600).
    pub(crate) fn open(&self, flags: libc::c_int) -> std::io::Result<File> {
        use std::os::unix::io::AsRawFd as _;
        open_in(self.directory.as_raw_fd(), &self.name, flags)
