use std::fs::{self, File, OpenOptions};
use std::io::{Seek, SeekFrom};
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;

use blit_core::copy::{open_resume_partial_held, resume_copy_through};

fn main() {
    let mut args = std::env::args().skip(1);
    let case = args.next().unwrap();
    let root = PathBuf::from(args.next().unwrap());
    match case.as_str() {
        "readonly" => {
            let dest = root.join("read-only");
            fs::write(&dest, b"original").unwrap();
            fs::set_permissions(&dest, fs::Permissions::from_mode(0o444)).unwrap();
            let before = fs::metadata(&dest).unwrap().permissions().mode() & 0o7777;
            let result = open_resume_partial_held(&dest, Some(0o100644), 8, None);
            let after = fs::metadata(&dest).unwrap().permissions().mode() & 0o7777;
            println!("before={before:04o} after={after:04o} result={result:?}");
        }
        "cursor" => {
            let src_path = root.join("source");
            let dst_path = root.join("destination");
            fs::write(&src_path, b"ABCD").unwrap();
            fs::write(&dst_path, b"xxABCD").unwrap();
            let mut src = File::open(&src_path).unwrap();
            let mut dst = OpenOptions::new().read(true).write(true).open(&dst_path).unwrap();
            dst.seek(SeekFrom::Start(2)).unwrap();
            let outcome = resume_copy_through(&mut src, 4, &mut dst, 6, &dst_path, 4).unwrap();
            let content = fs::read_to_string(&dst_path).unwrap();
            println!("source=ABCD destination={content} skipped={} transferred={}",
                     outcome.blocks_skipped, outcome.bytes_transferred);
        }
        _ => panic!("unrecognized case"),
    }
}
