        (Some(dir), Some(name)) => dir_stats.lookup(dir, name, &repair.phase_probe),
        // A destination path with no parent/name split (a bare root) has
        // no directory to sweep; only the stat can speak to it.
        _ => DirStatLookup::Fallback,
